WITH with_windows AS (SELECT id, product_name, category, price, stock_qty, AVG(cost) OVER w_part AS running_avg_cost, SUM(cost) OVER w_part AS running_sum_cost, MIN(cost) OVER w_part AS running_min_cost, ROW_NUMBER() OVER w_grp AS row_seq FROM products WINDOW w_part AS (PARTITION BY supplier_id, category ORDER BY stock_qty, id ROWS BETWEEN UNBOUNDED PRECEDING AND CURRENT ROW), w_grp AS (PARTITION BY brand ORDER BY launch_date DESC, id)) SELECT id, product_name, price, stock_qty, running_sum_cost, running_min_cost, row_seq FROM with_windows;
